css:
.article-preview {
  color: var(--color-article-ink);
}
.article-preview .article-body {
  max-width: 40rem;
  margin: 0 auto;
  padding: 1.5rem 1.25rem 3rem;
  font-size: 1rem;
  line-height: 1.875;
}
.article-preview .article-body > :first-child { margin-top: 0; }
.article-preview .article-body h1,
.article-preview .article-body h2,
.article-preview .article-body h3,
.article-preview .article-body h4,
.article-preview .article-body h5,
.article-preview .article-body h6 {
  color: var(--color-article-heading);
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.2;
  margin: 2rem 0 0.75rem;
}
.article-preview .article-body h1 { font-size: 2.25rem; }
.article-preview .article-body h2 { font-size: 1.75rem; border-bottom: 0.0625rem solid var(--color-article-line); padding-bottom: 0.5rem; }
.article-preview .article-body h3 { font-size: 1.375rem; }
.article-preview .article-body h4 { font-size: 1.125rem; }
.article-preview .article-body h5 { font-size: 1rem; }
.article-preview .article-body h6 { font-size: 0.875rem; text-transform: uppercase; letter-spacing: 0.08em; }
.article-preview .article-body p,
.article-preview .article-body ul,
.article-preview .article-body ol,
.article-preview .article-body blockquote,
.article-preview .article-body pre,
.article-preview .article-body table,
.article-preview .article-body figure { margin: 1rem 0; }
.article-preview .article-body a { color: var(--color-article-heading); text-decoration: underline; text-underline-offset: 0.15em; }
.article-preview .article-body strong { color: var(--color-article-heading); font-weight: 700; }
.article-preview .article-body del { color: var(--color-article-muted); }
.article-preview .article-body blockquote { border-left: 0.25rem solid var(--color-article-accent); background: var(--color-article-tint); padding: 0.75rem 1rem; color: var(--color-article-muted); }
.article-preview .article-body ul { padding-left: 1.5rem; }
.article-preview .article-body ol { padding-left: 1.5rem; }
.article-preview .article-body li + li { margin-top: 0.35rem; }
.article-preview .article-body hr { border: 0; border-bottom: 0.0625rem solid var(--color-article-line); margin: 2rem 0; }
.article-preview .article-body code { background: var(--color-article-code-tint); border-radius: 0.25rem; color: var(--color-article-code); font-size: 0.88em; padding: 0.15em 0.35em; }
.article-preview .article-body pre { background: var(--color-article-code-surface); border: 0.0625rem solid var(--color-article-line); border-radius: 0.75rem; color: var(--color-article-code); overflow-x: auto; padding: 1rem; }
.article-preview .article-body pre code { background: transparent; color: inherit; padding: 0; }
.article-preview .article-body table { border-collapse: collapse; display: block; max-width: 100%; overflow-x: auto; }
.article-preview .article-body th,
.article-preview .article-body td { border: 0.0625rem solid var(--color-article-line); padding: 0.6rem 0.75rem; text-align: left; vertical-align: top; }
.article-preview .article-body th { background: var(--color-article-tint); color: var(--color-article-heading); }
.article-preview .article-body img { border-radius: 0.75rem; height: auto; max-width: 100%; display: block; }
.article-preview .article-body figcaption { color: var(--color-article-muted); font-size: 0.875rem; margin-top: 0.5rem; text-align: center; }
.article-preview .article-body input[type='checkbox'] { accent-color: var(--color-article-accent); margin: 0 0.5rem 0 0; }

.article-preview .article-body h1 { font-size: 2rem; line-height: 1.4; }
.article-preview .article-body h2 { font-size: 1.375rem; line-height: 1.5; }
.article-preview .article-body h3 { font-size: 1.125rem; line-height: 1.6; }
.article-preview .article-body h4 { font-size: 1rem; line-height: 1.75; }
.article-preview .article-body h5 { font-size: 0.9375rem; line-height: 1.75; }
.article-preview .article-body h6 { font-size: 0.875rem; line-height: 1.75; }
.article-preview .article-body p { margin: 1.25rem 0; }
.article-preview .article-body blockquote p { margin: 0.5rem 0; }
.article-preview .article-body table { font-size: 0.875rem; line-height: 1.75; }
.article-preview .article-body figcaption { font-size: 0.8125rem; line-height: 1.75; }

.article-preview .article-body h1 { text-align: center; font-weight: 600; letter-spacing: 0.06em; padding: 1rem 0; margin-bottom: 2rem; }
.article-preview .article-body h2 { text-align: center; color: var(--color-article-heading); border-top: 0.0625rem solid var(--color-article-line); border-bottom: 0.0625rem solid var(--color-article-line); padding: 0.75rem 0; margin: 2.5rem 0 1.25rem; font-weight: 600; letter-spacing: 0.04em; }
.article-preview .article-body h3 { font-weight: 600; letter-spacing: 0.02em; }
.article-preview .article-body blockquote { background: var(--color-article-quote-surface); color: var(--color-article-ink); border-left: 0; border-top: 0.0625rem solid var(--color-article-line); border-bottom: 0.0625rem solid var(--color-article-line); padding: 1rem 1.25rem; margin: 2rem 0; }
.article-preview .article-body hr { margin: 2.5rem auto; border-bottom: 0.0625rem solid var(--color-article-accent); }
.article-preview .article-body img { border-radius: 0.25rem; height: auto; max-width: 100%; display: block; }
.article-preview .article-body figcaption { letter-spacing: 0.03em; }
